141	// filterOverrideBreakdownByAxis returns rows where Axis == axis. Empty axis
142	// returns the input unchanged. Rows are returned in the same deterministic
143	// order produced by the aggregator.
144	func filterOverrideBreakdownByAxis(rows []rootfizeau.OverrideClassBucket, axis string) []rootfizeau.OverrideClassBucket {
145		if axis == "" {
146			return rows
147		}
148		out := make([]rootfizeau.OverrideClassBucket, 0, len(rows))
149		for _, r := range rows {
150			if r.Axis == axis {
151				out = append(out, r)
152			}
153		}
154		return out
155	}
