31	// TestRouteStatus_modelsPopulatedFromProviders verifies RouteStatus reports
32	// live provider/model candidates, not configured route tables.
33	func TestRouteStatus_modelsPopulatedFromProviders(t *testing.T) {
34		sc := &fakeServiceConfig{
35			providers: map[string]ServiceProviderEntry{
36				"bragi":      {Type: "lmstudio", BaseURL: "http://bragi.invalid/v1", Model: "qwen3-27b"},
37				"openrouter": {Type: "openrouter", BaseURL: "https://openrouter.invalid/v1", Model: "qwen3-27b"},
38			},
39			names: []string{"bragi", "openrouter"},
40		}
41		svc := newTestService(t, ServiceOptions{ServiceConfig: sc})
42	
43		report, err := svc.RouteStatus(context.Background())
44		if err != nil {
45			t.Fatalf("RouteStatus: %v", err)
46		}
47		if len(report.Routes) != 1 {
48			t.Fatalf("Routes: got %d, want 1", len(report.Routes))
49		}
50	
51		entry := report.Routes[0]
52		if entry.Model != "qwen3-27b" {
53			t.Errorf("Model: got %q, want %q", entry.Model, "qwen3-27b")
54		}
55		if entry.Strategy != "auto" {
56			t.Errorf("Strategy: got %q, want auto", entry.Strategy)
57		}
58		if len(entry.Candidates) != 2 {
59			t.Fatalf("Candidates: got %d, want 2", len(entry.Candidates))
60		}
61		if entry.Candidates[0].Provider != "bragi" {
62			t.Errorf("Candidates[0].Provider: got %q, want %q", entry.Candidates[0].Provider, "bragi")
63		}
64		if entry.Candidates[0].ServerInstance == "" {
65			t.Errorf("Candidates[0].ServerInstance should be populated: %#v", entry.Candidates[0])
66		}
67		if entry.Candidates[1].Provider != "openrouter" {
68			t.Errorf("Candidates[1].Provider: got %q, want %q", entry.Candidates[1].Provider, "openrouter")
69		}
70		// No cooldowns set — both should be healthy.
71		for i, c := range entry.Candidates {
72			if !c.Healthy {
73				t.Errorf("Candidates[%d].Healthy: got false, want true", i)
74			}
75			if c.Cooldown != nil {
76				t.Errorf("Candidates[%d].Cooldown: expected nil", i)
77			}
78		}
79	}
