81	// TestRouteStatus_lastDecisionCached verifies that calling ResolveRoute and
82	// then RouteStatus surfaces the cached LastDecision on the matching entry.
83	func TestRouteStatus_lastDecisionCached(t *testing.T) {
84		// Build a minimal ServiceConfig that satisfies the routing engine.
85		sc := &fakeServiceConfig{
86			providers: map[string]ServiceProviderEntry{
87				"bragi": {Type: "lmstudio", BaseURL: "http://127.0.0.1:9999/v1", Model: "qwen3-27b"},
88			},
89			names:       []string{"bragi"},
90			defaultName: "bragi",
91		}
92	
93		// Seed registry with the "fiz" harness available so routing can resolve.
94		reg := harnesses.NewRegistry()
95		svc := &service{
96			opts:     ServiceOptions{ServiceConfig: sc},
97			registry: reg,
98		}
99	
100		// Inject a decision directly into the cache (simulating a resolved route)
101		// since ResolveRoute may fail without a real provider.
102		dec := &RouteDecision{
103			Harness:        "fiz",
104			Provider:       "bragi",
105			Endpoint:       "desk-a",
106			ServerInstance: "desk-a",
107			Model:          "qwen3-27b",
108			Reason:         "test",
109			Sticky:         RouteStickyState{KeyPresent: true, Assignment: "reused", ServerInstance: "desk-a", Reason: "live sticky lease reused"},
110		}
111		svc.cacheRouteDecision("qwen3-27b", dec)
112	
113		report, err := svc.RouteStatus(context.Background())
114		if err != nil {
115			t.Fatalf("RouteStatus: %v", err)
116		}
117		if len(report.Routes) != 1 {
118			t.Fatalf("Routes: got %d, want 1", len(report.Routes))
119		}
120		entry := report.Routes[0]
121		if entry.LastDecision == nil {
122			t.Fatal("LastDecision: expected non-nil after ResolveRoute")
123		}
124		if entry.LastDecision.Provider != "bragi" {
125			t.Errorf("LastDecision.Provider: got %q, want %q", entry.LastDecision.Provider, "bragi")
126		}
127		if entry.LastDecision.ServerInstance == "" {
128			t.Errorf("LastDecision.ServerInstance should be populated: %#v", entry.LastDecision)
129		}
130		if entry.LastDecision.Model != "qwen3-27b" {
131			t.Errorf("LastDecision.Model: got %q, want %q", entry.LastDecision.Model, "qwen3-27b")
132		}
133		if entry.LastDecisionAt.IsZero() {
134			t.Error("LastDecisionAt: should be non-zero")
135		}
136		if entry.SelectedEndpoint != "desk-a" {
137			t.Fatalf("SelectedEndpoint = %q, want desk-a", entry.SelectedEndpoint)
138		}
139		if entry.SelectedServerInstance == "" {
140			t.Fatalf("SelectedServerInstance should be populated: %#v", entry)
141		}
142		if !entry.Sticky.KeyPresent || entry.Sticky.Assignment != "reused" {
143			t.Fatalf("Sticky = %#v, want reused sticky evidence", entry.Sticky)
144		}
145	}
