9	// Normalize returns the explicit server instance when present, otherwise a
10	// deterministic identity derived from baseURL's host and port.
11	//
12	// The derived identity ignores URL path components so provider endpoints that
13	// differ only by `/v1` root normalization still collapse to the same
14	// server-instance label.
15	func Normalize(baseURL, explicit string) string {
16		if trimmed := strings.TrimSpace(explicit); trimmed != "" {
17			return trimmed
18		}
19		return FromBaseURL(baseURL)
20	}
21	
22	// FromBaseURL derives a stable server-instance label from the URL host/port.
23	func FromBaseURL(baseURL string) string {
24		trimmed := strings.TrimSpace(baseURL)
25		if trimmed == "" {
26			return ""
27		}
28		parsed, err := url.Parse(trimmed)
29		if err != nil {
30			return fallbackHostPort(trimmed)
31		}
32		host := strings.TrimSpace(parsed.Hostname())
33		if host == "" {
34			return fallbackHostPort(trimmed)
35		}
36		port := strings.TrimSpace(parsed.Port())
37		if port == "" {
38			return host
39		}
40		return host + ":" + port
41	}
42	
43	func fallbackHostPort(raw string) string {
44		raw = strings.TrimSpace(raw)
45		if raw == "" {
46			return ""
47		}
48		host, port, err := net.SplitHostPort(raw)
49		if err == nil && host != "" {
50			if port != "" {
51				return host + ":" + port
52			}
53			return host
54		}
55		raw = strings.TrimPrefix(raw, "http://")
56		raw = strings.TrimPrefix(raw, "https://")
57		raw = strings.TrimSuffix(raw, "/v1")
58		raw = strings.TrimSuffix(raw, "/")
59		return raw
60	}
