114	// parseRouteStatusOverridesSince parses --since as a Go duration. Empty
115	// means the default 7d window.
116	func parseRouteStatusOverridesSince(spec string) (time.Duration, error) {
117		if spec == "" {
118			return defaultRouteStatusOverridesWindow, nil
119		}
120		d, err := time.ParseDuration(spec)
121		if err != nil {
122			return 0, fmt.Errorf("--since: %w", err)
123		}
124		if d <= 0 {
125			return 0, fmt.Errorf("--since: must be positive, got %s", spec)
126		}
127		return d, nil
128	}
