197	func writeRouteStatusOverridesText(w io.Writer, out routeStatusOverridesOutput) {
198		fmt.Fprintf(w, "Window: %s .. %s (%s)\n",
199			out.WindowStart.Format(time.RFC3339),
200			out.WindowEnd.Format(time.RFC3339),
201			windowDurationLabel(out.Since))
202		if out.AxisFilter != "" {
203			fmt.Fprintf(w, "Axis filter: %s\n", out.AxisFilter)
204		}
205		fmt.Fprintf(w, "Auto-acceptance rate: %.3f (%d / %d)\n",
206			out.AutoAcceptanceRate,
207			out.TotalRequests-out.TotalOverrides,
208			out.TotalRequests)
209		fmt.Fprintf(w, "Override disagreement rate: %.3f (%d overrides)\n",
210			out.OverrideDisagreementRate,
211			out.TotalOverrides)
212	
213		if len(out.OverrideClassBreakdown) == 0 {
214			fmt.Fprintln(w)
215			fmt.Fprintln(w, "No override events recorded in this window.")
216			return
217		}
218	
219		fmt.Fprintln(w)
220		tw := tabwriter.NewWriter(w, 0, 0, 2, ' ', 0)
221		fmt.Fprintln(tw, "PROMPT_FEATURES\tAXIS\tMATCH\tCOUNT\tSUCCESS%\tSUCCESS\tSTALLED\tFAILED\tCANCELLED\tUNKNOWN")
222		for _, b := range sortOverrideBreakdownForDisplay(out.OverrideClassBreakdown) {
223			successPct := bucketSuccessRate(b) * 100
224			fmt.Fprintf(tw, "%s\t%s\t%t\t%d\t%.1f%%\t%d\t%d\t%d\t%d\t%d\n",
225				b.PromptFeatureBucket, b.Axis, b.Match, b.Count, successPct,
226				b.SuccessOutcomes, b.StalledOutcomes, b.FailedOutcomes,
227				b.CancelledOutcomes, b.UnknownOutcomes)
228		}
229		_ = tw.Flush()
230	}
