121	func routingWeights(cfg *agentConfig.Config) (reliability, performance, load, cost, capability float64) {
122		reliability = 0.35
123		performance = 0.20
124		load = 0.15
125		cost = 0.20
126		capability = 0.10
127		if cfg == nil {
128			return
129		}
130		if cfg.Routing.ReliabilityWeight > 0 {
131			reliability = cfg.Routing.ReliabilityWeight
132		}
133		if cfg.Routing.PerformanceWeight > 0 {
134			performance = cfg.Routing.PerformanceWeight
135		}
136		if cfg.Routing.LoadWeight > 0 {
137			load = cfg.Routing.LoadWeight
138		}
139		if cfg.Routing.CostWeight > 0 {
140			cost = cfg.Routing.CostWeight
141		}
142		if cfg.Routing.CapabilityWeight > 0 {
143			capability = cfg.Routing.CapabilityWeight
144		}
145		total := reliability + performance + load + cost + capability
146		if total <= 0 {
147			return 0.35, 0.20, 0.15, 0.20, 0.10
148		}
149		return reliability / total, performance / total, load / total, cost / total, capability / total
150	}
