152	func buildSmartRoutePlan(cfg *agentConfig.Config, workDir, routeKey, routeModelRef string, allowDeprecated bool, explicitRoute *routePlanConfig, scorer CandidateScorer) (smartRoutePlan, error) {
153		now := time.Now().UTC()
154		plan := smartRoutePlan{
155			RouteKey:          routeKey,
156			RequestedModel:    routeKey,
157			RequestedModelRef: routeModelRef,
158			Strategy:          "smart",
159			scorer:            scorer,
160		}
161	
162		var route routePlanConfig
163		if explicitRoute != nil {
164			route = *explicitRoute
165			if strings.TrimSpace(route.Strategy) != "" {
166				plan.Strategy = route.Strategy
167			}
168		} else {
169			route = synthesizeIntentRoute(cfg, routeKey, routeModelRef)
170		}
171	
172		history, err := readSmartRoutingHistory(sessionLogDir(workDir, cfg), routeKey, now, routingHistoryWindow(cfg))
173		if err != nil {
174			return plan, err
175		}
176		healthState, err := loadRouteHealthState(workDir, routeKey)
177		if err != nil {
178			healthState = routeHealthState{Failures: make(map[string]time.Time)}
179		}
180		counter, err := readAndIncrementRouteCounter(workDir, routeKey)
181		if err != nil {
182			counter = 0
183		}
184	
185		cat, _ := modelcatalog.Load(modelcatalog.LoadOptions{})
186		obs, _ := observations.LoadStore(observations.DefaultStorePath())
187	
188		modelProbeCache := make(map[string]providerModelProbe)
189		plan.Candidates = make([]smartRouteCandidate, 0, len(route.Candidates))
190		finalCandidates := make([]routePlanCandidate, 0, len(route.Candidates))
191		for _, candidate := range route.Candidates {
192			inspected, resolvedCandidate := inspectSmartRouteCandidate(cfg, routeKey, routeModelRef, allowDeprecated, candidate, history[candidate.Provider], healthState, modelProbeCache, cat, obs)
193			plan.Candidates = append(plan.Candidates, inspected)
194			finalCandidates = append(finalCandidates, resolvedCandidate)
195		}
196		if len(finalCandidates) == 0 {
197			return plan, fmt.Errorf("config: no routing candidates available for model %q", routeKey)
198		}
199		route.Candidates = finalCandidates
200	
201		if strings.TrimSpace(route.Strategy) == "smart" || explicitRoute == nil {
202			order := scoreSmartRouteCandidates(&plan, counter, cfg)
203			if len(order) == 0 {
204				return plan, fmt.Errorf("config: no healthy providers available for model %q", routeKey)
205			}
206			plan.Order = order
207			return plan, nil
208		}
209	
210		order := routeAttemptOrder(route, counter, healthState, routeHealthCooldown(cfg))
211		if len(order) == 0 {
212			return plan, fmt.Errorf("config: no route candidates available for model %q", routeKey)
213		}
214		plan.Order = order
215		return plan, nil
216	}
