218	func synthesizeIntentRoute(cfg *agentConfig.Config, requestedModel, requestedModelRef string) routePlanConfig {
219		candidates := make([]routePlanCandidate, 0, len(cfg.ProviderNames()))
220		for _, provider := range cfg.ProviderNames() {
221			model := requestedModel
222			if requestedModelRef != "" {
223				model = ""
224			}
225			candidates = append(candidates, routePlanCandidate{
226				Provider: provider,
227				Model:    model,
228			})
229		}
230		return routePlanConfig{
231			Strategy:   "smart",
232			Candidates: candidates,
233		}
234	}
