236	func inspectSmartRouteCandidate(cfg *agentConfig.Config, routeKey, routeModelRef string, allowDeprecated bool, candidate routePlanCandidate, history smartRouteHistory, healthState routeHealthState, modelProbeCache map[string]providerModelProbe, cat *modelcatalog.Catalog, obs *observations.Store) (smartRouteCandidate, routePlanCandidate) {
237		report := smartRouteCandidate{
238			Provider:         candidate.Provider,
239			Model:            candidate.Model,
240			Priority:         candidate.Priority,
241			Reliability:      history.ReliabilityScore(),
242			AvgDurationMs:    history.AvgDurationMs,
243			OutputTokensPerS: history.AvgOutputTokensPerS,
244			RecentSelections: history.RecentSelections,
245			AvgCostPer1KTok:  history.AvgKnownCostPer1KTok,
246			LastSelectedAt:   history.LastSelectedAt,
247		}
248	
249		overrides := agentConfig.ProviderOverrides{}
250		if candidate.Model != "" {
251			overrides.Model = candidate.Model
252		} else if routeModelRef != "" {
253			overrides.ModelRef = routeModelRef
254		} else {
255			overrides.Model = routeKey
256		}
257	
258		overrides.AllowDeprecated = allowDeprecated
259		pc, _, err := cfg.ResolveProviderConfig(candidate.Provider, overrides)
260		if err != nil {
261			report.Healthy = false
262			report.Reason = err.Error()
263			return report, candidate
264		}
265		if pc.Model != "" {
266			report.Model = pc.Model
267			candidate.Model = pc.Model
268		}
269	
270		if failedAt, ok := healthState.Failures[candidate.Provider]; ok {
271			if time.Since(failedAt) < routeHealthCooldown(cfg) {
272				report.Healthy = false
273				report.Reason = fmt.Sprintf("cooldown until %s", failedAt.Add(routeHealthCooldown(cfg)).Format(time.RFC3339))
274				return report, candidate
275			}
276		}
277	
278		probe, ok := modelProbeCache[candidate.Provider]
279		if !ok {
280			probe = probeProviderModels(pc, routingProbeTimeout(cfg))
281			modelProbeCache[candidate.Provider] = probe
282		}
283		healthy, matchedModel, reason := evaluateProviderCandidate(pc, routeKey, candidate.Model, probe)
284		report.Healthy = healthy
285		if matchedModel != "" {
286			report.Model = matchedModel
287			candidate.Model = matchedModel
288		}
289		report.Reason = reason
290	
291		// Populate catalog-sourced benchmark data.
292		resolvedModel := report.Model
293		if cat != nil && resolvedModel != "" {
294			if entry, ok := cat.LookupModel(resolvedModel); ok {
295				report.SWEBenchVerified = entry.SWEBenchVerified
296			}
297		}
298	
299		// Populate observed speed from the observations store.
300		if obs != nil && resolvedModel != "" {
301			if speed, ok := obs.MeanSpeed(observations.Key{ProviderSystem: candidate.Provider, Model: resolvedModel}); ok {
302				report.ObservedTokensPerSec = speed
303			}
304		}
305	
306		return report, candidate
307	}
