309	func scoreSmartRouteCandidates(plan *smartRoutePlan, counter int, cfg *agentConfig.Config) []int {
310		healthy := make([]int, 0, len(plan.Candidates))
311		for i, candidate := range plan.Candidates {
312			if candidate.Healthy {
313				healthy = append(healthy, i)
314			}
315		}
316		if len(healthy) == 0 {
317			return nil
318		}
319	
320		reliabilityWeight, performanceWeight, loadWeight, costWeight, capabilityWeight := routingWeights(cfg)
321	
322		minDuration, maxDuration := 0.0, 0.0
323		minCost, maxCost := 0.0, 0.0
324		minObsSpeed, maxObsSpeed := 0.0, 0.0
325		minBench, maxBench := 0.0, 0.0
326		maxSelections := 0
327		firstDuration := true
328		firstCost := true
329		firstObsSpeed := true
330		firstBench := true
331		for _, idx := range healthy {
332			candidate := plan.Candidates[idx]
333			if candidate.AvgDurationMs > 0 {
334				if firstDuration {
335					minDuration, maxDuration = candidate.AvgDurationMs, candidate.AvgDurationMs
336					firstDuration = false
337				} else {
338					if candidate.AvgDurationMs < minDuration {
339						minDuration = candidate.AvgDurationMs
340					}
341					if candidate.AvgDurationMs > maxDuration {
342						maxDuration = candidate.AvgDurationMs
343					}
344				}
345			}
346			if candidate.AvgCostPer1KTok != nil {
347				cost := *candidate.AvgCostPer1KTok
348				if firstCost {
349					minCost, maxCost = cost, cost
350					firstCost = false
351				} else {
352					if cost < minCost {
353						minCost = cost
354					}
355					if cost > maxCost {
356						maxCost = cost
357					}
358				}
359			}
360			if candidate.ObservedTokensPerSec > 0 {
361				if firstObsSpeed {
362					minObsSpeed, maxObsSpeed = candidate.ObservedTokensPerSec, candidate.ObservedTokensPerSec
363					firstObsSpeed = false
364				} else {
365					if candidate.ObservedTokensPerSec < minObsSpeed {
366						minObsSpeed = candidate.ObservedTokensPerSec
367					}
368					if candidate.ObservedTokensPerSec > maxObsSpeed {
369						maxObsSpeed = candidate.ObservedTokensPerSec
370					}
371				}
372			}
373			if candidate.SWEBenchVerified > 0 {
374				if firstBench {
375					minBench, maxBench = candidate.SWEBenchVerified, candidate.SWEBenchVerified
376					firstBench = false
377				} else {
378					if candidate.SWEBenchVerified < minBench {
379						minBench = candidate.SWEBenchVerified
380					}
381					if candidate.SWEBenchVerified > maxBench {
382						maxBench = candidate.SWEBenchVerified
383					}
384				}
385			}
386			if candidate.RecentSelections > maxSelections {
387				maxSelections = candidate.RecentSelections
388			}
389		}
390	
391		for _, idx := range healthy {
392			candidate := &plan.Candidates[idx]
393	
394			// Performance: prefer observed speed when available, fall back to session history latency.
395			performanceScore := 0.5
396			if !firstObsSpeed && candidate.ObservedTokensPerSec > 0 {
397				if maxObsSpeed == minObsSpeed {
398					performanceScore = 1.0
399				} else {
400					performanceScore = (candidate.ObservedTokensPerSec - minObsSpeed) / (maxObsSpeed - minObsSpeed)
401				}
402			} else if !firstDuration && candidate.AvgDurationMs > 0 {
403				if maxDuration == minDuration {
404					performanceScore = 1.0
405				} else {
406					performanceScore = 1 - ((candidate.AvgDurationMs - minDuration) / (maxDuration - minDuration))
407				}
408			}
409	
410			loadScore := 1.0
411			if maxSelections > 0 {
412				loadScore = 1 - (float64(candidate.RecentSelections) / float64(maxSelections))
413			}
414	
415			costScore := 0.5
416			if !firstCost && candidate.AvgCostPer1KTok != nil {
417				if maxCost == minCost {
418					costScore = 1.0
419				} else {
420					costScore = 1 - ((*candidate.AvgCostPer1KTok - minCost) / (maxCost - minCost))
421				}
422			}
423	
424			// Capability: normalize swe_bench_verified across healthy candidates.
425			capScore := 0.5 // neutral when no data
426			if !firstBench && candidate.SWEBenchVerified > 0 {
427				if maxBench == minBench {
428					capScore = 1.0
429				} else {
430					capScore = (candidate.SWEBenchVerified - minBench) / (maxBench - minBench)
431				}
432			}
433			candidate.CapabilityScore = capScore
434	
435			priorityScore := 0.0
436			if candidate.Priority > 0 {
437				priorityScore = float64(candidate.Priority) / 1000
438			}
439	
440			candidate.Score = candidate.Reliability*reliabilityWeight +
441				performanceScore*performanceWeight +
442				loadScore*loadWeight +
443				costScore*costWeight +
444				capScore*capabilityWeight +
445				priorityScore
446	
447			if plan.scorer != nil {
448				adjusted := plan.scorer.Score(candidate.Provider, candidate.Model, candidate.Score)
449				if adjusted < 0 {
450					candidate.Healthy = false
451					candidate.Reason = "excluded by scorer"
452					continue
453				}
454				candidate.Score = adjusted
455			}
456		}
457	
458		// Re-filter healthy after scorer may have excluded candidates.
459		if plan.scorer != nil {
460			filtered := healthy[:0]
461			for _, idx := range healthy {
462				if plan.Candidates[idx].Healthy {
463					filtered = append(filtered, idx)
464				}
465			}
466			healthy = filtered
467			if len(healthy) == 0 {
468				return nil
469			}
470		}
471	
472		sort.SliceStable(healthy, func(i, j int) bool {
473			left := plan.Candidates[healthy[i]]
474			right := plan.Candidates[healthy[j]]
475			if left.Score != right.Score {
476				return left.Score > right.Score
477			}
478			if left.RecentSelections != right.RecentSelections {
479				return left.RecentSelections < right.RecentSelections
480			}
481			if left.Priority != right.Priority {
482				return left.Priority > right.Priority
483			}
484			return left.Provider < right.Provider
485		})
486	
487		bestScore := plan.Candidates[healthy[0]].Score
488		bestTier := make([]int, 0, len(healthy))
489		rest := make([]int, 0, len(healthy))
490		for _, idx := range healthy {
491			if abs(plan.Candidates[idx].Score-bestScore) < 0.01 {
492				bestTier = append(bestTier, idx)
493				continue
494			}
495			rest = append(rest, idx)
496		}
497		if len(bestTier) > 1 {
498			offset := counter % len(bestTier)
499			bestTier = append(bestTier[offset:], bestTier[:offset]...)
500		}
501		return append(bestTier, rest...)
502	}
