504	func evaluateProviderCandidate(pc agentConfig.ProviderConfig, requestedModel, configuredModel string, probe providerModelProbe) (bool, string, string) {
505		switch pc.Type {
506		case "anthropic":
507			if pc.APIKey == "" {
508				return false, "", "missing API key"
509			}
510			if requestedModel != "" && configuredModel != "" {
511				requestedFamily := modelFamily(requestedModel)
512				configuredFamily := modelFamily(configuredModel)
513				if requestedFamily != "" && configuredFamily != "" && requestedFamily != configuredFamily {
514					return false, "", "requested model not compatible with provider"
515				}
516			}
517			if configuredModel != "" {
518				return true, configuredModel, "configured"
519			}
520			return true, requestedModel, "configured"
521		default:
522			if probe.err != nil {
523				return false, "", probe.err.Error()
524			}
525			match := bestModelMatch(requestedModel, configuredModel, probe.models)
526			if requestedModel != "" && match == "" {
527				if configuredModel != "" && !sameModelIntent(requestedModel, configuredModel) {
528					return true, configuredModel, "configured (unlisted)"
529				}
530				return false, "", "requested model unavailable"
531			}
532			if match == "" {
533				match = configuredModel
534			}
535			if match == "" && len(probe.models) > 0 {
536				match = probe.models[0]
537			}
538			// Normalize bare model names to the server's canonical IDs.
539			// This handles e.g. "qwen3-coder-next" → "qwen/qwen3-coder-next"
540			// which is required for LM Studio JIT model loading.
541			if match != "" {
542				normalized, err := rootfizeau.NormalizeModelID(match, probe.models)
543				if err != nil {
544					return false, "", err.Error()
545				}
546				match = normalized
547			}
548			return true, match, fmt.Sprintf("inference-ready (%d models)", len(probe.models))
549		}
550	}
551	
552	func bestModelMatch(requestedModel, configuredModel string, listed []string) string {
553		if requestedModel == "" {
554			if configuredModel != "" {
555				return configuredModel
556			}
557			if len(listed) > 0 {
558				return listed[0]
559			}
560			return ""
561		}
562		if configuredModel != "" && sameModelIntent(requestedModel, configuredModel) {
563			return configuredModel
564		}
565		for _, model := range listed {
566			if sameModelIntent(requestedModel, model) {
567				return model
568			}
569		}
570		if configuredModel != "" {
571			return requestedModel
572		}
573		return ""
574	}
575	
576	func sameModelIntent(requestedModel, candidate string) bool {
577		left := comparableModelName(requestedModel)
578		right := comparableModelName(candidate)
579		if left == "" || right == "" {
580			return false
581		}
582		return left == right || strings.Contains(right, left) || strings.Contains(left, right)
583	}
584	
585	func comparableModelName(model string) string {
586		model = strings.ToLower(strings.TrimSpace(model))
587		if slash := strings.LastIndex(model, "/"); slash >= 0 {
588			model = model[slash+1:]
589		}
590		if idx := strings.LastIndex(model, "-20"); idx > 0 {
591			model = model[:idx]
592		}
593		model = strings.TrimSuffix(model, "-latest")
594		return model
595	}
596	
597	func modelFamily(model string) string {
598		model = strings.ToLower(model)
599		switch {
600		case strings.Contains(model, "claude"):
601			return "claude"
602		case strings.Contains(model, "qwen"):
603			return "qwen"
604		case strings.Contains(model, "gpt"):
605			return "gpt"
606		case strings.Contains(model, "gemini"):
607			return "gemini"
608		case strings.Contains(model, "llama"):
609			return "llama"
610		default:
611			return ""
612		}
613	}
