615	func probeProviderModels(pc agentConfig.ProviderConfig, timeout time.Duration) providerModelProbe {
616		if pc.Type == "anthropic" {
617			if pc.APIKey == "" {
618				return providerModelProbe{err: fmt.Errorf("missing API key")}
619			}
620			return providerModelProbe{}
621		}
622		if strings.TrimSpace(pc.BaseURL) == "" {
623			return providerModelProbe{err: fmt.Errorf("no URL configured")}
624		}
625	
626		ctx, cancel := context.WithTimeout(context.Background(), timeout)
627		defer cancel()
628	
629		models, err := rootfizeau.DiscoverModels(ctx, pc.BaseURL, pc.APIKey)
630		if err != nil {
631			return providerModelProbe{err: err}
632		}
633		return providerModelProbe{models: models}
634	}
