636	func readSmartRoutingHistory(logDir, routeKey string, now time.Time, historyWindow time.Duration) (map[string]smartRouteHistory, error) {
637		entries, err := os.ReadDir(logDir)
638		if err != nil {
639			if os.IsNotExist(err) {
640				return map[string]smartRouteHistory{}, nil
641			}
642			return nil, fmt.Errorf("routing history: reading log dir: %w", err)
643		}
644		cutoff := now.Add(-historyWindow)
645		loadCutoff := now.Add(-minDuration(historyWindow, defaultRoutingLoadWindow))
646		type accumulator struct {
647			successes        int
648			failures         int
649			durationMs       int64
650			outputTokPerSSum float64
651			costPer1KSum     float64
652			costSamples      int
653			recentSelections int
654			lastSelectedAt   time.Time
655		}
656		accumulators := make(map[string]*accumulator)
657		for _, entry := range entries {
658			if entry.IsDir() || filepath.Ext(entry.Name()) != ".jsonl" {
659				continue
660			}
661			events, err := rootfizeau.ReadSessionEvents(filepath.Join(logDir, entry.Name()))
662			if err != nil {
663				continue
664			}
665			for _, event := range events {
666				if event.Type != rootfizeau.EventSessionEnd {
667					continue
668				}
669				var end rootfizeau.SessionEndData
670				if err := json.Unmarshal(event.Data, &end); err != nil {
671					continue
672				}
673				if end.SelectedProvider == "" {
674					continue
675				}
676				intent := end.RequestedModel
677				if intent == "" {
678					intent = end.ResolvedModel
679				}
680				if intent == "" {
681					intent = end.Model
682				}
683				if routeKey != "" && intent != routeKey {
684					continue
685				}
686				if event.Timestamp.Before(cutoff) {
687					continue
688				}
689				acc := accumulators[end.SelectedProvider]
690				if acc == nil {
691					acc = &accumulator{}
692					accumulators[end.SelectedProvider] = acc
693				}
694				if event.Timestamp.After(acc.lastSelectedAt) {
695					acc.lastSelectedAt = event.Timestamp
696				}
697				if event.Timestamp.After(loadCutoff) {
698					acc.recentSelections++
699				}
700				if end.Status == rootfizeau.StatusSuccess {
701					acc.successes++
702					acc.durationMs += end.DurationMs
703					if end.DurationMs > 0 && end.Tokens.Output > 0 {
704						acc.outputTokPerSSum += float64(end.Tokens.Output) / (float64(end.DurationMs) / 1000)
705					}
706					if end.CostUSD != nil && *end.CostUSD >= 0 && end.Tokens.Total > 0 {
707						acc.costPer1KSum += (*end.CostUSD / float64(end.Tokens.Total)) * 1000
708						acc.costSamples++
709					}
710				} else {
711					acc.failures++
712				}
713			}
714		}
715	
716		result := make(map[string]smartRouteHistory, len(accumulators))
717		for provider, acc := range accumulators {
718			stats := smartRouteHistory{
719				Samples:          acc.successes + acc.failures,
720				Successes:        acc.successes,
721				Failures:         acc.failures,
722				RecentSelections: acc.recentSelections,
723				LastSelectedAt:   acc.lastSelectedAt,
724			}
725			if acc.successes > 0 {
726				stats.AvgDurationMs = float64(acc.durationMs) / float64(acc.successes)
727				stats.AvgOutputTokensPerS = acc.outputTokPerSSum / float64(acc.successes)
728			}
729			if acc.costSamples > 0 {
730				value := acc.costPer1KSum / float64(acc.costSamples)
731				stats.AvgKnownCostPer1KTok = &value
732			}
733			result[provider] = stats
734		}
735		return result, nil
736	}
737	
738	func minDuration(left, right time.Duration) time.Duration {
739		if left <= 0 {
740			return right
741		}
742		if right <= 0 || left < right {
743			return left
744		}
745		return right
746	}
747	
748	func abs(v float64) float64 {
749		if v < 0 {
750			return -v
751		}
752		return v
753	}
