755	// routeStatusComponents mirrors fizeau.RouteCandidateComponents in the
756	// route-status JSON envelope. Operators read these to answer "why did the
757	// router pick X?" without parsing the free-form Reason string.
758	type routeStatusComponents struct {
759		Power            int     `json:"power"`
760		Cost             float64 `json:"cost"`
761		CostClass        string  `json:"cost_class,omitempty"`
762		LatencyMS        float64 `json:"latency_ms"`
763		SpeedTPS         float64 `json:"speed_tps"`
764		Utilization      float64 `json:"utilization"`
765		SuccessRate      float64 `json:"success_rate"`
