1053	func orderedCandidates(plan smartRoutePlan) []smartRouteCandidate {
1054		if len(plan.Candidates) == 0 {
1055			return nil
1056		}
1057		ordered := make([]smartRouteCandidate, 0, len(plan.Candidates))
1058		seen := make(map[int]struct{}, len(plan.Candidates))
1059		for _, idx := range plan.Order {
1060			if idx < 0 || idx >= len(plan.Candidates) {
1061				continue
1062			}
1063			ordered = append(ordered, plan.Candidates[idx])
1064			seen[idx] = struct{}{}
1065		}
1066		for idx, candidate := range plan.Candidates {
1067			if _, ok := seen[idx]; ok {
1068				continue
1069			}
1070			ordered = append(ordered, candidate)
1071		}
1072		return ordered
1073	}
1074	
1075	func truncate(value string, n int) string {
1076		if n <= 0 || len(value) <= n {
1077			return value
1078		}
1079		if n <= 2 {
1080			return value[:n]
1081		}
1082		return value[:n-2] + ".."
1083	}
1084	
1085	func stickyLabel(present bool) string {
1086		if present {
1087			return "present"
1088		}
1089		return "absent"
1090	}
1091	
1092	func labelOrUnknown(v string) string {
1093		if v == "" {
1094			return "unknown"
1095		}
1096		return v
1097	}
