34	// TestRouteStatusOverridesSinceFilter verifies that --since trims the
35	// breakdown window. Three session logs are written: one 1h ago (inside
36	// every window), one 48h ago (inside 7d but outside 24h), one 30d ago
37	// (outside both).
38	func TestRouteStatusOverridesSinceFilter(t *testing.T) {
39		workDir := t.TempDir()
40		logDir := filepath.Join(workDir, ".fizeau", "sessions")
41		if err := os.MkdirAll(logDir, 0o755); err != nil {
42			t.Fatalf("mkdir: %v", err)
43		}
44		now := time.Now().UTC()
45		writeOverrideSessionLog(t, logDir, "s-1h", now.Add(-time.Hour), "harness", false, "success")
46		writeOverrideSessionLog(t, logDir, "s-48h", now.Add(-48*time.Hour), "harness", false, "success")
47		writeOverrideSessionLog(t, logDir, "s-30d", now.Add(-30*24*time.Hour), "harness", false, "success")
48	
49		// 24h window: only s-1h is inside.
50		out := runRouteStatusOverridesJSON(t, workDir, "24h", "", now)
51		if out.TotalOverrides != 1 {
52			t.Fatalf("--since=24h: TotalOverrides = %d, want 1", out.TotalOverrides)
53		}
54		totalCount := 0
55		for _, b := range out.OverrideClassBreakdown {
56			totalCount += b.Count
57		}
58		if totalCount != 1 {
59			t.Errorf("--since=24h: breakdown count sum = %d, want 1", totalCount)
60		}
61	
62		// Default 7d window (--since="" → 168h): s-1h + s-48h.
63		out = runRouteStatusOverridesJSON(t, workDir, "", "", now)
64		if out.TotalOverrides != 2 {
65			t.Fatalf("default 7d: TotalOverrides = %d, want 2", out.TotalOverrides)
66		}
67	
68		// 168h is the explicit equivalent of the default and must produce the
69		// same result as the default window.
70		out2 := runRouteStatusOverridesJSON(t, workDir, "168h", "", now)
71		if out2.TotalOverrides != out.TotalOverrides {
72			t.Errorf("168h vs default: TotalOverrides %d vs %d should match",
73				out2.TotalOverrides, out.TotalOverrides)
74		}
75	
76		// 24h header text mentions the chosen window.
77		textOut, _ := runRouteStatusOverridesText(t, workDir, "24h", "", now)
78		if !strings.Contains(textOut, "Window: ") {
79			t.Errorf("text output missing Window header: %q", textOut)
80		}
81		if !strings.Contains(textOut, "24h") {
82			t.Errorf("text output should echo since=24h: %q", textOut)
83		}
84	}
