119	// ServerRoot strips a trailing /v1 path component from an OpenAI-compatible
120	// base URL while preserving the scheme, host, and any prefix path.
121	func ServerRoot(baseURL string) string {
122		trimmed := strings.TrimSpace(strings.TrimRight(baseURL, "/"))
123		if trimmed == "" {
124			return ""
125		}
126	
127		parsed, err := url.Parse(trimmed)
128		if err != nil {
129			return strings.TrimSuffix(trimmed, "/v1")
130		}
131	
132		parsed.Fragment = ""
133		parsed.RawQuery = ""
134		path := strings.TrimRight(parsed.Path, "/")
135		if strings.HasSuffix(path, "/v1") {
136			path = strings.TrimSuffix(path, "/v1")
137		}
138		parsed.Path = path
139		return strings.TrimRight(parsed.String(), "/")
140	}
