142	// ParsePrometheusMetricValue returns the first numeric value for metric from
143	// a Prometheus-style plaintext metrics body.
144	func ParsePrometheusMetricValue(body, metric string) (float64, bool) {
145		for _, line := range strings.Split(body, "\n") {
146			line = strings.TrimSpace(line)
147			if line == "" || strings.HasPrefix(line, "#") || !strings.HasPrefix(line, metric) {
148				continue
149			}
150			rest := strings.TrimSpace(strings.TrimPrefix(line, metric))
151			if strings.HasPrefix(rest, "{") {
152				if idx := strings.Index(rest, "}"); idx >= 0 {
153					rest = strings.TrimSpace(rest[idx+1:])
154				}
155			}
156			fields := strings.Fields(rest)
157			if len(fields) == 0 {
158				continue
159			}
160			val, err := strconv.ParseFloat(fields[0], 64)
161			if err == nil {
162				return val, true
163			}
164		}
165		return 0, false
166	}
