116	func recordInteractions(t *testing.T, client *http.Client, baseURL string, probeClient *http.Client, recordMode bool) {
117		t.Helper()
118		rootURL := serverRootURL(baseURL)
119		models := fetchModels(t, client, baseURL)
120		require.NotEmpty(t, models)
121		model := preferredRecordModel(models)
122	
123		idleMetrics := fetchMetrics(t, client, rootURL)
124		require.Equal(t, 0, idleMetrics.Running)
125		require.Equal(t, 0, idleMetrics.Waiting)
126		require.GreaterOrEqual(t, idleMetrics.CacheUsage, 0.0)
127		require.NotEmpty(t, idleMetrics.CacheMetric)
128	
129		_ = chatCompletion(t, client, baseURL, model, vllmRecordPrompt, vllmRequestMaxTokens)
130	
131		afterChatMetrics := fetchMetrics(t, client, rootURL)
132		require.GreaterOrEqual(t, afterChatMetrics.Running, 0)
133		require.GreaterOrEqual(t, afterChatMetrics.Waiting, 0)
134		require.NotEmpty(t, afterChatMetrics.CacheMetric)
135	
136		if recordMode {
137			loadResp, err := startStreamingLoadRequest(probeClient, strings.TrimRight(baseURL, "/"), model, vllmLoadPrompt, vllmLoadMaxTokens)
138			require.NoError(t, err)
139	
140			waitForMetric(t, probeClient, rootURL, func(s vllmMetricsSnapshot) bool {
141				return s.Running > 0
142			})
143	
144			loadMetrics := fetchMetrics(t, client, rootURL)
145			require.GreaterOrEqual(t, loadMetrics.Running, 1, "load metrics must capture an in-flight request")
146			require.GreaterOrEqual(t, loadMetrics.Waiting, 0)
147			require.NotEmpty(t, loadMetrics.CacheMetric)
148	
149			waitForMetric(t, probeClient, rootURL, func(s vllmMetricsSnapshot) bool {
150				return s.Running == 0
151			})
152	
153			_, _ = io.Copy(io.Discard, loadResp.Body)
154			require.NoError(t, loadResp.Body.Close())
155			return
156		}
157	
158		loadMetrics := fetchMetrics(t, client, rootURL)
159		require.GreaterOrEqual(t, loadMetrics.Running, 0)
160		require.GreaterOrEqual(t, loadMetrics.Waiting, 0)
161		require.NotEmpty(t, loadMetrics.CacheMetric)
162	}
