296	func parseVLLMMetrics(body string) (vllmMetricsSnapshot, error) {
297		out := vllmMetricsSnapshot{}
298		running, ok := parsePromMetricValue(body, "vllm:num_requests_running")
299		if !ok {
300			return out, fmt.Errorf("parse vllm:num_requests_running: not found")
301		}
302		waiting, ok := parsePromMetricValue(body, "vllm:num_requests_waiting")
303		if !ok {
304			return out, fmt.Errorf("parse vllm:num_requests_waiting: not found")
305		}
306		cacheMetric := "vllm:kv_cache_usage_perc"
307		cacheUsage, ok := parsePromMetricValue(body, cacheMetric)
308		if !ok {
309			cacheMetric = "vllm:gpu_cache_usage_perc"
310			cacheUsage, ok = parsePromMetricValue(body, cacheMetric)
311		}
312		if !ok {
313			return out, fmt.Errorf("parse vllm cache metric: kv_cache_usage_perc or gpu_cache_usage_perc not found")
314		}
315		out.Running = int(running)
316		out.Waiting = int(waiting)
317		out.CacheUsage = cacheUsage
318		out.CacheMetric = cacheMetric
319		return out, nil
320	}
321	
322	func parsePromMetricValue(body, metric string) (float64, bool) {
323		scanner := bufio.NewScanner(strings.NewReader(body))
324		for scanner.Scan() {
325			line := strings.TrimSpace(scanner.Text())
326			if line == "" || strings.HasPrefix(line, "#") || !strings.HasPrefix(line, metric) {
327				continue
328			}
329			rest := strings.TrimSpace(strings.TrimPrefix(line, metric))
330			if strings.HasPrefix(rest, "{") {
331				if idx := strings.Index(rest, "}"); idx >= 0 {
332					rest = strings.TrimSpace(rest[idx+1:])
333				}
334			}
335			fields := strings.Fields(rest)
336			if len(fields) == 0 {
337				continue
338			}
339			val, err := strconv.ParseFloat(fields[0], 64)
340			if err == nil {
341				return val, true
342			}
343		}
344		return 0, false
345	}
