389		ensureDockerImage(t, ctx, image)
390	
391		port := pickFreePort(t)
392		containerName := fmt.Sprintf("fizeau-vllm-%d", time.Now().UnixNano())
393		templateDir := filepath.Join(t.TempDir(), "templates")
394		require.NoError(t, os.MkdirAll(templateDir, 0o755))
395		templatePath := filepath.Join(templateDir, "simple-chat.jinja")
396		require.NoError(t, os.WriteFile(templatePath, []byte(simpleChatTemplate), 0o600))
397		args := []string{
398			"run", "-d", "--rm",
399			"--name", containerName,
400			"--network", "host",
401			"--shm-size=4g",
402			"--cap-add", "SYS_NICE",
403			"--security-opt", "seccomp=unconfined",
404			"-e", "HF_HOME=/tmp/huggingface",
405			"-e", "HF_HUB_DISABLE_TELEMETRY=1",
406			"-e", "VLLM_CPU_KVCACHE_SPACE=4",
407			"-e", "VLLM_CPU_NUM_OF_RESERVED_CPU=1",
408			"-v", templateDir + ":/templates",
409			image,
410			vllmRecordModel,
411			"--dtype=bfloat16",
412			"--max-model-len=128",
413			"--max-num-seqs=1",
414			"--max-num-batched-tokens=128",
415			"--host=127.0.0.1",
416			"--port", strconv.Itoa(port),
417			"--chat-template", "/templates/simple-chat.jinja",
418		}
419		out, err := exec.CommandContext(ctx, "docker", args...).CombinedOutput()
420		require.NoError(t, err, "docker run failed: %s", string(out))
421		containerID := strings.TrimSpace(string(out))
422		require.NotEmpty(t, containerID)
423	
424		baseURL := fmt.Sprintf("http://127.0.0.1:%d/v1", port)
425		probeClient := &http.Client{Timeout: 5 * time.Second}
426		waitForHTTP(t, probeClient, baseURL+"/models")
427	
428		return &vllmServer{
429			BaseURL:      baseURL,
430			DirectClient: probeClient,
431			stop: func() error {
432				stopCtx, stopCancel := context.WithTimeout(context.Background(), 30*time.Second)
433				defer stopCancel()
434				_, _ = exec.CommandContext(stopCtx, "docker", "rm", "-f", containerID).CombinedOutput()
435				return nil
436			},
437		}
438	}
