	// utilization is omitted when all-zero (omitempty on struct with no pointer fields set).
	assert.NotContains(t, startRaw, "utilization", "zero utilization state must be omitted")

	// Verify the end event too.
	var endRaw map[string]json.RawMessage
	require.NoError(t, json.Unmarshal(events[1].Data, &endRaw))
	assert.NotContains(t, endRaw, "sticky", "zero sticky state must be omitted from session.end")
	assert.NotContains(t, endRaw, "utilization", "zero utilization state must be omitted from session.end")
}

